 <!doctype html>
 <html lang="en">
   <head>
     <meta charset="utf-8" />
     <meta name="viewport" content="width=device-width, initial-scale=1" />
     <title>Terms Consent</title>
     <style>
       :root {
         color-scheme: light;
         --bg: #f5f7fb;
         --surface: #ffffff;
         --surface-2: #eef3ff;
         --text: #162033;
         --muted: #5d6b84;
         --border: #c9d4ea;
         --accent: #2f6bff;
         --accent-strong: #1f55d6;
         --shadow: 0 20px 50px rgba(22, 32, 51, 0.12);
       }

       * {
         box-sizing: border-box;
       }

       html {
         color: var(--text);
         background: var(--bg);
       }

       body {
         margin: 0;
         min-height: 100vh;
         font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
         line-height: 1.5;
       }

       .skip-link {
         position: absolute;
         left: 1rem;
         top: 1rem;
         padding: 0.75rem 1rem;
         border-radius: 999px;
         background: var(--surface);
         color: var(--text);
         text-decoration: none;
         transform: translateY(-200%);
         transition: transform 160ms ease;
         z-index: 10;
       }

       .skip-link:focus {
         transform: translateY(0);
         outline: 3px solid var(--accent);
         outline-offset: 2px;
       }

       main {
         min-height: 100vh;
         display: grid;
         place-items: center;
         padding: 5rem 1.25rem 2rem;
       }

       .card {
         width: min(100%, 28rem);
         background: var(--surface);
         border: 1px solid var(--border);
         border-radius: 24px;
         box-shadow: var(--shadow);
         padding: 2rem;
       }

       h1 {
         margin: 0 0 0.5rem;
         font-size: clamp(1.6rem, 3vw, 2.1rem);
         line-height: 1.15;
       }

       .lede {
         margin: 0 0 1.5rem;
         color: var(--muted);
       }

       form {
         display: grid;
         gap: 1.25rem;
       }

       .form-field {
         padding: 1rem;
         border-radius: 18px;
         background: var(--surface-2);
         border: 1px solid var(--border);
       }

       .consent-label {
         display: flex;
         align-items: flex-start;
         gap: 0.75rem;
         font-weight: 600;
         cursor: pointer;
       }

       .consent-label input {
         margin-top: 0.2rem;
         width: 1.125rem;
         height: 1.125rem;
         accent-color: var(--accent);
         flex: 0 0 auto;
       }

       .required-mark {
         color: var(--accent-strong);
       }

       .helper-text {
         margin: 0.5rem 0 0;
         color: var(--muted);
         font-size: 0.95rem;
       }

       .actions {
         display: flex;
         justify-content: flex-end;
       }

       button {
         border: 0;
         border-radius: 999px;
         padding: 0.9rem 1.35rem;
         background: linear-gradient(135deg, var(--accent), var(--accent-strong));
         color: #fff;
         font: inherit;
         font-weight: 700;
         cursor: pointer;
         box-shadow: 0 12px 24px rgba(47, 107, 255, 0.22);
       }

       button:focus-visible,
       input:focus-visible {
         outline: 3px solid #102a66;
         outline-offset: 3px;
       }

       button:hover {
         filter: brightness(1.03);
       }

       button:active {
         transform: translateY(1px);
       }

       .status {
         min-height: 1.5rem;
         margin: 0;
         color: var(--accent-strong);
         font-weight: 600;
       }

       @media (max-width: 480px) {
         .card {
           padding: 1.5rem;
           border-radius: 20px;
         }

         .actions {
           justify-content: stretch;
         }

         button {
           width: 100%;
         }
       }

       @media (forced-colors: active) {
         :root {
           --bg: Canvas;
           --surface: Canvas;
           --surface-2: Canvas;
           --text: CanvasText;
           --muted: CanvasText;
           --border: ButtonBorder;
           --accent: ButtonText;
           --accent-strong: ButtonText;
         }

         .skip-link,
         .card,
         .form-field,
         button {
           forced-color-adjust: auto;
           border: 1px solid ButtonBorder;
           background: Canvas;
           color: CanvasText;
           box-shadow: none;
         }

         button {
           background: ButtonFace;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#main">Skip to main content</a>

     <main id="main">
       <section class="card" aria-labelledby="page-title">
         <h1 id="page-title">Agree to the terms</h1>
         <p class="lede">Please confirm your consent before continuing.</p>

         <form id="consent-form">
           <div class="form-field">
             <label class="consent-label" for="terms">
               <input
                 id="terms"
                 name="terms"
                 type="checkbox"
                 required
                 aria-describedby="terms-help"
               />
               <span>
                 I agree to the terms of use <span class="required-mark" aria-hidden="true">*</span>
               </span>
             </label>
             <p class="helper-text" id="terms-help">You must agree to continue.</p>
           </div>

           <div class="actions">
             <button type="submit">Submit</button>
           </div>

           <p class="status" id="form-status" aria-live="polite"></p>
         </form>
       </section>
     </main>

     <script>
       const form = document.getElementById('consent-form');
       const checkbox = document.getElementById('terms');
       const status = document.getElementById('form-status');

       form.addEventListener('submit', (event) => {
         if (!checkbox.checkValidity()) {
           status.textContent = '';
           return;
         }

         event.preventDefault();
         status.textContent = 'Consent saved. Thanks for agreeing to the terms.';
       });
     </script>
   </body>
 </html>

